"""Generated by AI and reviewed. Not written by hand."""

import re

import pytest

from app.models.enums import Intent
from tests.seed_helpers import seed_buyorder_state, seed_listing, seed_sellorder_state


def row_order(html: str) -> list[str]:
    return re.findall(r'id=row-([^\s"]+)', html)


async def seed_priced_buyorders(db_session, prices):
    for listing_id, keys in prices.items():
        listing, _ = await seed_listing(db_session, listing_id=listing_id)
        await seed_buyorder_state(db_session, listing, user_keys=keys)


async def test_dashboard_renders(client):
    resp = await client.get("/")
    assert resp.status_code == 200
    assert "Only Beaten" in resp.text


async def test_buyorders_alias_renders(client):
    resp = await client.get("/buyorders")
    assert resp.status_code == 200
    assert "Only Beaten" in resp.text


async def test_dashboard_shows_seeded_buyorder(client, db_session):
    listing, _ = await seed_listing(db_session, listing_id="L1")
    await seed_buyorder_state(db_session, listing)
    resp = await client.get("/")
    assert resp.status_code == 200
    assert "id=row-L1" in resp.text
    assert "Key" in resp.text


async def test_dashboard_only_beaten_filter(client, db_session):
    l1, _ = await seed_listing(db_session, listing_id="L1")
    l2, _ = await seed_listing(db_session, listing_id="L2")
    await seed_buyorder_state(db_session, l1, is_outbid=True)
    await seed_buyorder_state(db_session, l2, is_outbid=False)
    resp = await client.get("/", params={"only_beaten": "True"})
    assert resp.status_code == 200
    assert "id=row-L1" in resp.text
    assert "id=row-L2" not in resp.text


async def test_dashboard_without_sort_renders_all_rows(client, db_session):
    await seed_priced_buyorders(db_session, {"L1": 10, "L2": 5, "L3": 7})
    resp = await client.get("/")
    assert set(row_order(resp.text)) == {"L1", "L2", "L3"}


async def test_dashboard_sort_asc(client, db_session):
    await seed_priced_buyorders(db_session, {"L1": 10, "L2": 5, "L3": 7})
    resp = await client.get("/", params={"sort": "asc"})
    assert row_order(resp.text) == ["L2", "L3", "L1"]


async def test_dashboard_sort_desc(client, db_session):
    await seed_priced_buyorders(db_session, {"L1": 10, "L2": 5, "L3": 7})
    resp = await client.get("/", params={"sort": "desc"})
    assert row_order(resp.text) == ["L1", "L3", "L2"]


async def test_dashboard_sort_tolerates_null_keys(client, db_session):
    l1, _ = await seed_listing(db_session, listing_id="L1")
    l2, _ = await seed_listing(db_session, listing_id="L2")
    await seed_buyorder_state(db_session, l1, user_keys=10)
    await seed_buyorder_state(db_session, l2, user_keys=None)
    resp = await client.get("/", params={"sort": "desc"})
    assert resp.status_code == 200
    assert row_order(resp.text) == ["L1", "L2"]


