@pytest.mark.parametrize(
    "sort, next_direction, arrow",
    [
        (None, "desc", None),
        ("asc", "desc", "&#9650;"),
        ("desc", "asc", "&#9660;"),
    ],
)
async def test_dashboard_sort_header_and_arrow(client, sort, next_direction, arrow):
    resp = await client.get("/", params={"sort": sort} if sort else {})
    assert f'href="/?sort={next_direction}' in resp.text
    if arrow:
        assert arrow in resp.text
    else:
        assert "&#9650;" not in resp.text
        assert "&#9660;" not in resp.text


